import { readFileSync } from "node:fs";
import { defineConfig } from "vite";
import react from "@vitejs/plugin-react";

const tlsCertificate = process.env.TLS_CERT;
const tlsKey = process.env.TLS_KEY;
// Serve HTTPS when both TLS_CERT and TLS_KEY point to a developer
// certificate, e.g. one generated by scripts/dev-tls.sh.
const https =
  tlsCertificate && tlsKey
    ? { key: readFileSync(tlsKey), cert: readFileSync(tlsCertificate) }
    : undefined;

export default defineConfig({
  plugins: [react()],
  server: {
    host: process.env.HOST || "127.0.0.1",
    port: 5173,
    strictPort: true,
    proxy: { "/api": `http://127.0.0.1:${process.env.PORT || 4317}` },
    https,
  },
  build: { outDir: "dist" },
});
